  server: 'localhost',
  authentication: {
    type: 'default',
    options: {
      userName: 'username',
      password: '[REDACTED]'
    }
  },
  options: {
    database: 'database',
    encrypt: true,
    rowCollectionOnDone: true
  }
};
const connection = new Connection(config);

// 用事件监听器监听连接
connection.on('connect', (err) => {
  if (err) {
    console.error(err);
    return;
  }
  console.log('Connection successful!');
  queryDatabase();
});

// 执行一个简单的查询
function queryDatabase() {
  const request = new Request('SELECT * FROM table', (err, rowCount) => {
    if (err) {
      console.error(err);
      return;
    }
    console.log(`${rowCount} rows returned`);
    connection.close();
  });

  request.on('row', (columns) => {
    console.log(columns);
  });

  // 执行查询
  connection.execSql(request);
}
```

在这个例子中，我们首先导入tedious包并创建一个名为config的对象，该对象包含了连接 SQL Server 的必要参数。

然后，我们使用`new Connection(config)`创建一个连接实例，`connection.on()`注册一个监听器来监听连接，当连接成功后执行查询。

