    cin >> n;
    string s;
    cin >> s;
    vector<int> memo(n, -1);
    int start = s.find('X');
    if (start == n - 1) {
        cout << "YES" << endl;
    } else if (start != string::npos && solve(s, start, memo)) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
    return 0;
}
